	}
	if cerr := f.Close(); err == nil {
		err = cerr
	}
	if err == nil {
		err = os.Rename(tmp, path)
	}
	if err != nil {
		os.Remove(tmp)
		return err
	}
	return nil
}

// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
func Load(path string) (*store.Store, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	_, st, err := decode(b, path)
	if err != nil {
		return nil, err
	}
	return store.FromState(st)
}

// Upgrade rewrites the snapshot at path as the current version. The original is first copied byte for byte to
// "<path>.v<old version>.bak". A file already at the current version is left alone, and a file of a newer version is
// refused with ErrUnsupportedVersion and left untouched.
func Upgrade(path string) error {
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	v, st, err := decode(b, path)
	if err != nil {
		return err
	}
	if v == Version {
		return nil
	}
	if err := writeFileAtomic(fmt.Sprintf("%s.v%d.bak", path, v), b); err != nil {
		return fmt.Errorf("snapshot %s: backup: %w", path, err)
	}
	return save(path, st, time.Now())
}

// decode returns the version of the snapshot b and its state, numbering the invoices of versions 1 and 2.
func decode(b []byte, path string) (int, store.State, error) {
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return 0, store.State{}, fmt.Errorf("snapshot %s: %w", path, err)
	}
	switch head.Version {
	case 1:
		st, err := migrateV1(b)
		if err != nil {
			return 0, store.State{}, fmt.Errorf("snapshot %s: version 1: %w", path, err)
		}
		numberInvoices(&st)
		return 1, st, nil
	case 2, 3:
		var f fileV3
		if err := json.Unmarshal(b, &f); err != nil {
			return 0, store.State{}, fmt.Errorf("snapshot %s: %w", path, err)
		}
		if head.Version == 2 {
			numberInvoices(&f.State)
		}
		return head.Version, f.State, nil
	default:
		return 0, store.State{}, fmt.Errorf("snapshot %s: %w %d", path, ErrUnsupportedVersion, head.Version)
	}
}

// numberInvoices gives the invoices of a file from before invoice numbers their numbers: per organization, in creation
// order (created_at, then ID), and sets each organization's next number after its last.
func numberInvoices(st *store.State) {
	sort.Slice(st.Invoices, func(i, j int) bool {
		a, b := st.Invoices[i], st.Invoices[j]
		if !a.CreatedAt.Equal(b.CreatedAt) {
			return a.CreatedAt.Before(b.CreatedAt)
		}
		return a.ID < b.ID
	})
	last := map[string]int{}
	for i := range st.Invoices {
		org := st.Invoices[i].OrgID
		last[org]++
		st.Invoices[i].Number = store.InvoiceNumber(last[org])
	}
	st.NextInvoiceNumbers = map[string]int{}
	for org, n := range last {
		st.NextInvoiceNumbers[org] = n + 1
	}
}

