func save(path string, state store.State, now time.Time) error {
	b, err := json.MarshalIndent(fileV3{Version: Version, SavedAt: now.UTC(), State: state}, "", "  ")
	if err != nil {
		return err
	}
	return writeFileAtomic(path, append(b, '\n'))
