func TestLoadVersion2NumbersInvoicesPerOrganization(t *testing.T) {
	const v2 = `{"version": 2, "saved_at": "2026-02-01T12:00:00Z", "state": {"seq": 20,
	  "orgs": [
	    {"id": "org_1", "name": "A", "plan": "free", "time_zone": "UTC", "tax_rate_bp": 0, "created_at": "2026-01-01T00:00:00Z"},
	    {"id": "org_2", "name": "B", "plan": "free", "time_zone": "UTC", "tax_rate_bp": 0, "created_at": "2026-01-01T00:00:00Z"}],
	  "invoices": [
	    {"id": "in_000010", "org_id": "org_1", "customer_id": "cus_1", "currency": "USD", "lines": [{"description": "x", "quantity": 1, "unit_amount": 5}], "status": "open", "created_at": "2026-01-03T00:00:00Z"},
	    {"id": "in_000011", "org_id": "org_2", "customer_id": "cus_2", "currency": "USD", "lines": [{"description": "x", "quantity": 1, "unit_amount": 5}], "status": "open", "created_at": "2026-01-02T00:00:00Z"},
	    {"id": "in_000013", "org_id": "org_1", "customer_id": "cus_1", "currency": "USD", "lines": [{"description": "x", "quantity": 1, "unit_amount": 5}], "status": "open", "created_at": "2026-01-01T00:00:00Z"},
	    {"id": "in_000012", "org_id": "org_1", "customer_id": "cus_1", "currency": "USD", "lines": [{"description": "x", "quantity": 1, "unit_amount": 5}], "status": "open", "created_at": "2026-01-01T00:00:00Z"}]}}`
	path := filepath.Join(t.TempDir(), "tally.json")
	if err := os.WriteFile(path, []byte(v2), 0o600); err != nil {
		t.Fatal(err)
	}
	st, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	// Ties on created_at are broken by ID, so in_000012 comes before in_000013.
	for id, want := range map[string]string{"in_000012": "INV-000001", "in_000013": "INV-000002", "in_000010": "INV-000003"} {
		if inv, ok := st.Invoice("org_1", id); !ok || inv.Number != want {
			t.Errorf("%s: number = %q, want %q", id, inv.Number, want)
		}
	}
	if inv, ok := st.Invoice("org_2", "in_000011"); !ok || inv.Number != "INV-000001" {
		t.Errorf("org_2's first invoice: number = %q, want INV-000001", inv.Number)
	}
	c, err := st.CreateCustomer("org_1", "Jane", "jane@example.com", time.Now())
	if err != nil {
		t.Fatal(err)
	}
	inv, err := st.CreateInvoice(store.Invoice{OrgID: "org_1", CustomerID: c.ID, Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 5}}}, time.Now())
	if err != nil || inv.Number != "INV-000004" {
		t.Fatalf("the next invoice's number = %q: %v", inv.Number, err)
	}
}

func TestSaveWritesVersion3AndNoTempFile(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	o, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, now)
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", now)
	_, _ = st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 5}}}, now)
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	if err := Save(st, path, now); err != nil {
		t.Fatal(err)
	}
	var head struct {
		Version int `json:"version"`
	}
	b, _ := os.ReadFile(path)
	if err := json.Unmarshal(b, &head); err != nil || head.Version != 3 || !strings.Contains(string(b), `"number": "INV-000001"`) {
		t.Fatalf("saved file: version %d, err %v", head.Version, err)
	}
	if entries, _ := os.ReadDir(dir); len(entries) != 1 {
		t.Fatalf("the folder holds %d entries after a save, want only the snapshot", len(entries))
	}
}

func TestFailedSaveLeavesNoTempFile(t *testing.T) {
