	path := filepath.Join(dir, "tally.json")
	v2 := []byte(`{"version": 2, "saved_at": "2026-02-01T12:00:00Z", "state": {"seq": 0}}` + "\n")
	if err := os.WriteFile(path, v2, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	if backup, err := os.ReadFile(filepath.Join(dir, "tally.json.v2.bak")); err != nil || !bytes.Equal(backup, v2) {
		t.Fatalf("backup = %q, %v", backup, err)
	}
}

func TestUpgradeLeavesVersion3Alone(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	if err := Save(store.New(), path, time.Now()); err != nil {
		t.Fatal(err)
	}
	before, _ := os.ReadFile(path)
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	if after, _ := os.ReadFile(path); !bytes.Equal(before, after) {
		t.Fatal("Upgrade changed a version 3 file")
	}
	if entries, _ := os.ReadDir(dir); len(entries) != 1 {
		t.Fatalf("Upgrade of a version 3 file left %d entries, want none extra", len(entries)-1)
	}
}

func TestUpgradeRefusesFutureVersions(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	future := []byte(`{"version": 4, "state": {}}`)
	if err := os.WriteFile(path, future, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); !errors.Is(err, ErrUnsupportedVersion) {
		t.Fatalf("err = %v", err)
	}
	if after, _ := os.ReadFile(path); !bytes.Equal(after, future) {
		t.Fatal("Upgrade changed a file of a newer version")
	}
	if entries, _ := os.ReadDir(dir); len(entries) != 1 {
		t.Fatalf("Upgrade left %d entries, want none extra", len(entries)-1)
	}
	if _, err := Load(path); !errors.Is(err, ErrUnsupportedVersion) {
		t.Fatalf("Load err = %v", err)
	}
}

